@import "tailwindcss";
@import "tw-animate-css";

/* Updated variant: Now we need a variant for light mode if you want to toggle back */
@custom-variant light (&:is(.light *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
}

/* --- 1. TELEGRAM DARK SIMULATION (Default) --- */
/* Moved from .dark to :root to make it the default */
:root {
  --radius: 0.5rem;

  --background: #1c1c1e;         /* Telegram Dark Bg */
  --foreground: #ffffff;         /* Telegram Text */

  --card: #2c2c2e;               /* Slightly lighter for cards */
  --card-foreground: #ffffff;

  --popover: #1c1c1e;
  --popover-foreground: #ffffff;

  --primary: #8774e1;            /* Telegram Dark Blue/Purple */
  --primary-foreground: #ffffff;

  --secondary: #000000;          /* Telegram Black Section */
  --secondary-foreground: #ffffff;

  --muted: #000000;
  --muted-foreground: #aaaaaa;   /* Telegram Hint */

  --accent: #2c2c2e;
  --accent-foreground: #ffffff;

  --destructive: #ff453a;
  --destructive-foreground: #ffffff;

  --border: #3d3d41;             /* Telegram Divider */
  --input: #3d3d41;
  --ring: #8774e1;
}

/* --- 2. TELEGRAM LIGHT SIMULATION (Manual Toggle) --- */
/* Moved from :root to .light class */
.light {
  --background: #ffffff;         /* Telegram Bg */
  --foreground: #000000;         /* Telegram Text */

  --card: #ffffff;
  --card-foreground: #000000;

  --popover: #ffffff;
  --popover-foreground: #000000;

  --primary: #3390ec;            /* Telegram Blue */
  --primary-foreground: #ffffff;

  --secondary: #f4f4f5;          /* Telegram Secondary Bg */
  --secondary-foreground: #000000;

  --muted: #f4f4f5;
  --muted-foreground: #707579;   /* Telegram Hint */

  --accent: #f4f4f5;
  --accent-foreground: #000000;

  --destructive: #ef4444;
  --destructive-foreground: #ffffff;

  --border: #dfe1e5;             /* Telegram Divider */
  --input: #dfe1e5;
  --ring: #3390ec;
}

/* --- 3. ACTUAL TELEGRAM INJECTION OVERRIDE --- */
/* 
   If the app is running inside Telegram, Telegram injects variables into :root.
   This block maps those injected variables to our semantic names.
   This has higher specificity, so it overrides the manual defaults above
   ONLY when inside Telegram.
*/
:root[style*="--tg-theme"] {
  --background: var(--tg-theme-bg-color);
  --foreground: var(--tg-theme-text-color);

  --card: var(--tg-theme-secondary-bg-color, var(--tg-theme-bg-color));
  --card-foreground: var(--tg-theme-text-color);

  --popover: var(--tg-theme-bg-color);
  --popover-foreground: var(--tg-theme-text-color);

  --primary: var(--tg-theme-button-color);
  --primary-foreground: var(--tg-theme-button-text-color);

  --secondary: var(--tg-theme-secondary-bg-color);
  --secondary-foreground: var(--tg-theme-text-color);

  --muted: var(--tg-theme-section-bg-color, var(--tg-theme-secondary-bg-color));
  --muted-foreground: var(--tg-theme-hint-color);

  --accent: var(--tg-theme-secondary-bg-color);
  --accent-foreground: var(--tg-theme-text-color);

  --border: var(--tg-theme-section-separator-color, var(--tg-theme-hint-color));
  --input: var(--tg-theme-section-separator-color, var(--tg-theme-hint-color));

  --ring: var(--tg-theme-button-color);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

